var r={en:`OrderCreated v1 contains customerId and total. Fraud analysis now needs currency and paymentMethod; older consumers must keep working.`,ua:`OrderCreated v1 містить customerId і total. Аналізу шахрайства потрібні currency та paymentMethod; старі споживачі мають працювати.`};var n={en:[`Add a schema/version contract and fraud-analysis consumer.`,`Plan compatible producer/consumer rollout and historical replay.`,`Identify PII risks and versioned contract tests.`],ua:[`Додай контракт схеми/версії та споживача аналізу шахрайства.`,`Сплануй сумісний реліз і відтворення історії.`,`Визнач ризики персональних даних і контрактні тести.`]};var s=[{en:`Old consumers still accept events during migration.`,ua:`Старі споживачі приймають події під час міграції.`},{en:`Failure of new fraud analysis does not roll back committed orders.`,ua:`Збій нового аналізу не відкочує збережені замовлення.`}];var t={scenario:r,tasks:n,checks:s};export{s as checks,t as default,r as scenario,n as tasks};